def transform(grid):
    h, w = len(grid), len(grid[0])

    # The large square cores are 7x7; protruding tabs identify their
    # orientation/placement but are not part of the compact output.
    tiles = {
        2: [[grid[r][c] for c in range(1, 8)] for r in range(0, 7)],
        3: [[grid[r][c] for c in range(12, 19)] for r in range(1, 8)],
        7: [[grid[r][c] for c in range(0, 7)] for r in range(11, 18)],
        8: [[grid[r][c] for c in range(9, 16)] for r in range(11, 18)],
    }

    # Rotate the marked 7 tile so the marker is at its upper-left.
    tiles[7] = [row[::-1] for row in tiles[7][::-1]]

    # Put the marker tile at upper-left, followed clockwise by the
    # remaining pieces.
    layout = [[7, 8], [2, 3]]
    out = [[0] * 14 for _ in range(14)]
    for br in range(2):
        for bc in range(2):
            tile = tiles[layout[br][bc]]
            for r in range(7):
                for c in range(7):
                    out[br * 7 + r][bc * 7 + c] = tile[r][c]
    return out
